<script setup lang="ts">
import { computed, reactive, ref, watch } from 'vue'
import { ElMessage } from 'element-plus'
import { post, amount, openEditor, refresh } from '../api/client'
import { labels } from '../catalog'
import RefSelect from '../components/RefSelect.vue'
import ResourceView from './ResourceView.vue'
const values=reactive<Record<string,any>>({p:'39.90',c:'15.00',f:'4.00',b:'1.00',t:'1.00',a:'6.00',r:0.08,l:'8.00'})
const result=ref<any>(null),stress=ref<any>(null),error=ref(''),candidate=ref<string|null>(null),evidence=ref<string|null>(null),loading=ref(false),cash=reactive<any>({daily_orders:5,upfront_cost:'20',settlement_days:7,refund_reserve:'100',advertising_budget:'50'}),cashResult=ref<string|null>(null)
const stressInputs=computed(()=>({...values,p:Math.max(0,Number(values.p)-5).toFixed(4),a:(Number(values.a)+4).toFixed(4),r:Math.max(Number(values.r),.15),l:Math.max(Number(values.l),10).toFixed(4)}))
async function calculate(){loading.value=true;error.value='';try{result.value=await post('/profit/calculate',values);stress.value=await post('/profit/calculate',stressInputs.value)}catch(e:any){error.value=e.message}finally{loading.value=false}}
async function save(){if(!candidate.value||!evidence.value){error.value='保存情景前请选择候选商品和核验证据';return}loading.value=true;try{await post('/profits',{...values,candidate_id:candidate.value,evidence_id:evidence.value,label:'NORMAL'});await post('/profits',{...stressInputs.value,candidate_id:candidate.value,evidence_id:evidence.value,label:'STRESS'});refresh.value++;ElMessage.success('正常与压力情景已分别保存，历史情景保留')}catch(e:any){error.value=e.message}finally{loading.value=false}}
async function calculateCash(){try{cashResult.value=(await post('/profit/cashflow',cash)).cash_required}catch(e:any){error.value=e.message}}
let timer:ReturnType<typeof setTimeout>;watch(values,()=>{clearTimeout(timer);timer=setTimeout(calculate,300)},{immediate:true})
</script>
<template>
  <section class="page-heading"><div><p class="eyebrow">利润中心</p><h1>算清每笔支付订单的贡献</h1><p class="muted">包括获客成本和退款损失，固定成本及人工另计。</p></div></section><el-alert v-if="error" :title="error" type="error" :closable="false" class="mb16"/>
  <div class="profit-grid"><section class="panel"><div class="panel-heading"><h3>正常情景参数</h3><span class="muted">金额：CNY / 支付订单</span></div><el-form label-position="top" class="record-form"><el-form-item v-for="key in Object.keys(values)" :key="key" :label="labels[key]"><el-input-number v-if="key==='r'" v-model="values[key]" :min="0" :max="1" :step="0.01" :controls="false" style="width:100%"/><el-input v-else v-model="values[key]"><template #prefix>¥</template></el-input></el-form-item></el-form><p class="help-note">全退净损失 L 不含广告，已扣除可退采购款及费用。部分退款通过实际订单账本登记。</p></section>
  <section class="panel result-panel" v-loading="loading"><div class="panel-heading"><h3>经济性结果</h3><el-tag effect="plain">确定性计算</el-tag></div><template v-if="result"><p class="muted">正常情景 · 每支付订单期望贡献</p><div class="hero-number" :class="{negative:Number(result.contribution)<0}"><small>¥</small>{{result.display_contribution}}</div><div class="mini-metrics"><div><span>盈亏平衡 CAC</span><strong>¥{{amount(result.max_cac)}}</strong></div><div><span>贡献率</span><strong>{{result.contribution_rate===null?'—':(result.contribution_rate*100).toFixed(1)+'%'}}</strong></div></div><div class="stress-box"><div><strong>联合压力情景</strong><p>售价 -5 元，广告 +4 元，全退率至少15%，全退损失至少10元</p></div><strong :class="{negative:Number(stress?.contribution)<0}">¥{{amount(stress?.contribution)}}</strong></div><el-alert v-if="Number(stress?.contribution)<0" title="压力情景贡献为负，不能通过测款经济性审核" type="warning" :closable="false" show-icon/></template><div class="formula-note">E = (1 − r) × (P − C − F − B − T) − r × L − A</div></section></div>
  <section class="panel mt24"><div class="panel-heading"><div><h3>保存到候选商品</h3><p class="muted">保存时冻结当前主供报价版本；更换报价后需要重新计算。</p></div></div><div class="save-scenario"><RefSelect v-model="candidate" kind="candidates"/><RefSelect v-model="evidence" kind="evidence"/><el-button type="primary" :loading="loading" @click="save">保存正常与压力情景</el-button></div></section>
  <section class="panel mt24"><div class="panel-heading"><div><h3>周转资金估算</h3><p class="muted">按前置成本和结算滞后估算，实际余额及冻结风险仍需核验。</p></div><strong v-if="cashResult" class="positive">预计需要 ¥{{amount(cashResult)}}</strong></div><div class="cash-form"><el-form-item label="日均支付订单"><el-input-number v-model="cash.daily_orders" :min="0" :controls="false"/></el-form-item><el-form-item label="每单前置现金"><el-input v-model="cash.upfront_cost"/></el-form-item><el-form-item label="结算滞后天数"><el-input-number v-model="cash.settlement_days" :min="0" :controls="false"/></el-form-item><el-form-item label="退款准备金"><el-input v-model="cash.refund_reserve"/></el-form-item><el-form-item label="投放预算"><el-input v-model="cash.advertising_budget"/></el-form-item><el-button @click="calculateCash">估算资金</el-button></div></section>
  <h3 class="mt24">已保存的利润情景</h3><ResourceView resource-kind="profits" embedded/>
</template>
